/*
    Basic implementation of Troy James Sobotka's AgX display rendering transform: https://github.com/sobotka/AgX.
*/

// https://www.shadertoy.com/view/43yfRh
float AgX_tf(float x)
{
    bool u = x >= 0.61376220703125;

    float k = u ? 1.2275244140625 - x : x;

   #if 1
    // min rel err
    float a = (0.7823   - 0.150163 * k) * k;
    float b =  0.735882 - 1.19897  * k;
   #else
    // min abs err
    float a = (0.77085           - 0.1               * k) * k;
    float b =  0.736149499672221 - 1.199405064761082 * k;
   #endif

    float ab = (a * b) * inversesqrt(a*a + b*b);

    return 0.8402324908443617 * x + ab * (u ? 1.0 : -1.0);
}

vec3 AgX_tf(vec3 col)
{
    return vec3(AgX_tf(col.r), 
                AgX_tf(col.g), 
                AgX_tf(col.b));
}

// nested polynomial fit (~1.33x faster)
vec3 AgX_tfB(vec3 x)
{
    x = (((2.3756 * x - 3.5265) * x + 0.4727) * x - 0.218  ) * x + 0.5815  ;
    x = (((1.7907 * x + 0.6957) * x - 1.0095) * x - 1.23219) * x + 0.716327;

    return x;
}


vec3 AgX(vec3 col)
{
    const mat3 fm = mat3(0.842479062253094 , 0.0423282422610123, 0.0423756549057051, 
                         0.0784335999999992, 0.878468636469772 , 0.0784336,
                         0.0792237451477643, 0.0791661274605434, 0.879142973793104);

    const mat3 im = mat3( 1.1968790051201739 ,-0.052896851757456176,-0.05297163551444379, 
                         -0.09802088114013677, 1.1519031299041727  ,-0.0980434501171241,
                         -0.09902974407972047,-0.09896117684484335 , 1.151073672641161);

    col = fm * col;

    // log2 remapping
    {
        const float mn =-12.47393;
        const float mx = 4.026069;

        const float a = 1.0 / (mx - mn);
        const float b = -mn * a;

        col = clamp(log2(col) * a + b, 0.0, 1.0);
    }

    // default contrast transfer function
    col = AgX_tf(col);

    col = im * col;

    return col;
}

vec3 miniAgX(vec3 x)
{
    x = mat3(0.84, 0.04, 0.04,
             0.08, 0.88, 0.08,
             0.08, 0.08, 0.88) * x;

    x = clamp(log2(x) * 0.0606 + 0.756, 0.0, 1.0);

    x = (((2.3756 * x - 3.5265) * x + 0.4727) * x - 0.218  ) * x + 0.5815  ;
    x = (((1.7907 * x + 0.6957) * x - 1.0095) * x - 1.23219) * x + 0.716327;

    x = mat3( 1.20, -0.05, -0.05,
             -0.10,  1.15, -0.10,
             -0.10, -0.10,  1.15) * x;

    return x;
}


void mainImage( out vec4 outCol, in vec2 uv0 )
{
    vec3 col = vec3(0.0);

    col = Hue_to_RGB(uv0.y / iResolution.y);
    col *= pow(uv0.x / iResolution.x, 8.0);
    col *= exp2(14.0);

   #if 1

    #if 1
    col = miniAgX(col);
    #else
    col = AgX(col);
    #endif

    #if 0
    if(col.r < 0.0 || col.g < 0.0 || col.b < 0.0 || col.r > 1.0 || col.g > 1.0 || col.b > 1.0) col = vec3(1.0, 0.0, 1.0);
    #elif 0
    if(col.r <= 0.0 || col.g <= 0.0 || col.b <= 0.0 || col.r >= 1.0 || col.g >= 1.0 || col.b >= 1.0) col = vec3(0.0, 1.0, 1.0);
    #endif

    outCol = vec4(col, 1.0);

   #else

    // makeshift tonemappig for comparison
    float L0 = dot(col, vec3(0.2126, 0.7152, 0.0722));
    float Lt = L0 / (1.0 + L0);
    col = mix(col, vec3(L0), Lt * 0.25);// desat
    col /= 1.0 + col;

    outCol = vec4(GammaEncode(clamp01(col)), 1.0); 

   #endif
}

#define PixelCount iResolution.xy
#define clamp01(x) clamp(x, 0.0, 1.0)
#define rsqrt inversesqrt

const float Pi = 3.14159265359;
const float Pi05 = Pi * 0.5;
const float Pi2  = Pi * 2.0;
const float RcpPi= 1.0 / Pi;

float Pow2(float x) {return x*x;}
float Pow3(float x) {return x*x*x;}
float Pow4(float x) {return Pow2(Pow2(x));}

float GammaEncode(float x) {return pow(x, 1.0 / 2.2);}
vec2 GammaEncode(vec2 x) {return pow(x, vec2(1.0 / 2.2));}
vec3 GammaEncode(vec3 x) {return pow(x, vec3(1.0 / 2.2));}
vec4 GammaEncode(vec4 x) {return pow(x, vec4(1.0 / 2.2));}

float ddxyLen(float v) { return length(vec2(dFdx(v), dFdy(v))); }
float ddxyRcpLen(float v) { return rsqrt( Pow2(dFdx(v)) + Pow2(dFdy(v)) ); }


float rescale(float v) { return v * ddxyRcpLen(v); }

float Graph(float f, float b)
{
    return clamp01(1.0 - (abs(rescale(f))-0.5-b)); 
}


float Line(float u, float b) { return Graph(u, b); }
float Lines(float u, float b) { return Graph(sin(u * Pi), b); }

float Grid(vec2 uv, float b)
{
    float xl = Lines(uv.x, b);    
    float yl = Lines(uv.y, b);

    return max(xl, yl);
}

float Cross(vec2 uv, float b)
{
    float xl = Line(uv.x, b);    
    float yl = Line(uv.y, b);

    return max(xl, yl);
}

float Dot(vec2 uv, vec2 dp, float dr)
{
    float v = length(uv - dp) - dr;

    if(v > dr) return 0.0;

    v *= ddxyRcpLen(v);
    v = 1.0 - clamp(v * 1.0, 0.0, 1.0);

    return v;
}

vec3 Hue_to_RGB(float hue)
{
    float H6 = hue * 6.0;

	float R =       abs(H6 - 3.0) - 1.0;
	float G = 2.0 - abs(H6 - 2.0);
	float B = 2.0 - abs(H6 - 4.0);

	return clamp(vec3(R, G, B), 0.0, 1.0);
}

float RGB_to_Hue(vec3 rgb)
{
    float v = (rgb.r - rgb.g - rgb.b) *  (1.0/6.0) + (1.0/3.0);

    return (rgb.b < rgb.g ? -v : v) + 0.5;     
}

vec3 RGB_to_HSV(vec3 rgb)
{
    float v = max(rgb.r, max(rgb.g, rgb.b));

    if(v == 0.0) return vec3(0.0);

    rgb /= v;

    float ds = min(rgb.r, min(rgb.g, rgb.b));
    float s = 1.0 - ds;

    if(ds == 1.0) return vec3(0.0, 0.0, v);

    rgb = (rgb - ds) / s;

    float h = RGB_to_Hue(rgb);

    return vec3(h, s, v);
}
